package com.shabakaty.cinemana.local;
import android.app.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.view.*;import android.widget.*;
/** Shared dark controls for local account and Continue Watching actions. */
public final class AccountUi {
 public static int dp(Context c,int n){return Math.round(n*c.getResources().getDisplayMetrics().density);}
 public static GradientDrawable shape(Context c,int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(c,radius));return d;}
 public static void button(Button button,boolean destructive){Context c=button.getContext();button.setAllCaps(false);button.setTextColor(Color.WHITE);button.setTextSize(13);button.setMinHeight(dp(c,46));button.setMinimumHeight(dp(c,46));button.setPadding(dp(c,8),dp(c,4),dp(c,8),dp(c,4));button.setBackground(shape(c,destructive?0xffc5120c:0xff303236,12));button.setBackgroundTintList(null);}
 public static class Builder extends AlertDialog.Builder {public Builder(Context c){super(c);}public AlertDialog show(){AlertDialog d=super.show();style(d);return d;}}
 public static void style(AlertDialog dialog){Window window=dialog.getWindow();if(window==null)return;window.setBackgroundDrawable(shape(dialog.getContext(),0xff242629,18));colors(window.getDecorView());ListView list=dialog.getListView();if(list!=null)list.setOnHierarchyChangeListener(new ViewGroup.OnHierarchyChangeListener(){public void onChildViewAdded(View parent,View child){colors(child);}public void onChildViewRemoved(View parent,View child){}});for(int id:new int[]{DialogInterface.BUTTON_POSITIVE,DialogInterface.BUTTON_NEGATIVE,DialogInterface.BUTTON_NEUTRAL}){Button b=dialog.getButton(id);if(b!=null)button(b,id==DialogInterface.BUTTON_POSITIVE);}}
 static void colors(View view){if(view instanceof TextView){((TextView)view).setTextColor(Color.WHITE);if(view instanceof EditText)((EditText)view).setHintTextColor(0xffb5b8bd);}if(view instanceof ViewGroup)for(int n=0;n<((ViewGroup)view).getChildCount();n++)colors(((ViewGroup)view).getChildAt(n));}
 public static void actions(View anchor,Runnable details,Runnable remove){Context c=anchor.getContext();Dialog dialog=new Dialog(c);LinearLayout panel=new LinearLayout(c);panel.setOrientation(1);panel.setLayoutDirection(View.LAYOUT_DIRECTION_RTL);panel.setPadding(dp(c,18),dp(c,16),dp(c,18),dp(c,24));panel.setBackground(shape(c,0xff242629,20));
  TextView title=new TextView(c);title.setText("خيارات العمل");title.setTextColor(Color.WHITE);title.setTextSize(19);title.setPadding(dp(c,8),dp(c,4),dp(c,8),dp(c,16));panel.addView(title);
  action(panel,"تفاصيل العمل",android.R.drawable.ic_menu_info_details,false,()->{dialog.dismiss();details.run();});action(panel,"حذف من أكمل المشاهدة",android.R.drawable.ic_menu_delete,true,()->{dialog.dismiss();remove.run();});action(panel,"إغلاق",android.R.drawable.ic_menu_close_clear_cancel,false,()->dialog.dismiss());
  dialog.setContentView(panel);Window window=dialog.getWindow();if(window!=null){window.setBackgroundDrawableResource(android.R.color.transparent);window.setLayout(-1,-2);window.setGravity(Gravity.BOTTOM);}dialog.show();if(window!=null)window.setLayout(-1,-2);
 }
 static void action(LinearLayout panel,String label,int icon,boolean danger,Runnable run){Context c=panel.getContext();LinearLayout row=new LinearLayout(c);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(c,14),0,dp(c,14),0);row.setBackground(shape(c,0xff303236,12));ImageView image=new ImageView(c);image.setImageResource(icon);image.setColorFilter(danger?0xffff6862:Color.WHITE);row.addView(image,new LinearLayout.LayoutParams(dp(c,24),dp(c,24)));TextView text=new TextView(c);text.setText(label);text.setTextColor(danger?0xffff7770:Color.WHITE);text.setTextSize(16);text.setPadding(dp(c,14),0,dp(c,14),0);row.addView(text,new LinearLayout.LayoutParams(-1,-2));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(c,54));p.topMargin=dp(c,8);panel.addView(row,p);row.setOnClickListener(v->run.run());}
 public static void resume(Object binding,boolean enabled){try{View icon=(View)binding.getClass().getField("W").get(binding);TextView text=(TextView)binding.getClass().getField("X").get(binding);if(!enabled)return;icon.setVisibility(View.VISIBLE);text.setVisibility(View.VISIBLE);text.setText("أكمل");text.setTextColor(Color.WHITE);drawIcon(icon,"ic_btn_play");}catch(Exception e){LocalRuntime.failure("resume_overlay",e);}}
 public static void watched(Object binding){try{View view=(View)binding.getClass().getField("Y").get(binding);view.post(()->{view.getOverlay().clear();if(view.getVisibility()==View.VISIBLE)drawIcon(view,"ic_watched");});}catch(Exception e){LocalRuntime.failure("watched_overlay",e);}}
 static void drawIcon(View view,String name){view.post(()->{try{int id=view.getResources().getIdentifier(name,"drawable",view.getContext().getPackageName());if(id==0)return;Drawable d=view.getResources().getDrawable(id,view.getContext().getTheme()).mutate();d.setTint(Color.WHITE);int size=dp(view.getContext(),30),left=(view.getWidth()-size)/2,top=(view.getHeight()-size)/2;d.setBounds(left,top,left+size,top+size);view.getOverlay().clear();view.getOverlay().add(d);}catch(Exception e){LocalRuntime.failure("overlay_icon",e);}});}
}
